head.script:
scwin.gVar = {
    "cRef" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > getDataListInfo]<br/>Textarea 컴포넌트에 바인딩된 DataCollection 정보를 반환합니다.",
    "validation" : [
        "DataCollection 의 ID 와 ref 속성값을 객체로 반환하여야 합니다.",
        "DataCollection 이 바인딩되지 않은 경우 null 을 반환하여야 합니다.",
        "반환된 객체의 id 속성은 바인딩 된 DataCollection 의 렌더링 ID 값을 가져야 합니다.",
        "반환된 객체의 ref 속성은 컴포넌트의 ref 속성값을 가져야 합니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (style 은 strTarget 에서 직접 정의 → 중복 정의 금지)
    let properties = {
        ref: scwin.gVar["cRef"],
    };

    let cList = $c.gcm.createCList(properties);

    // empty textarea 동적 생성 (ref 바인딩 테스트에는 비어있는 textarea 사용)
    let grp_comp = $c.gcm.getTestGroup('');

    let strTarget = '<xf:textarea ' + $c.gcm.strNameSpace + ' ' + cList + ' id="" style="width:300px; height:100px;"></xf:textarea>';

    scwin.target1 = await $p.dynamicCreate(
        'target1',
        'textarea',
        strTarget,
        grp_comp
    );
}
